"""Uncertainty budget for one KX-100 reading (first-order GUM), from MANUAL.md sections 5 and 7."""

import math


def combined_uncertainty_pct(
    reading_dbm: float, freq_hz: float, averages: int, power_range: str, gamma_source: float
) -> float:
    """Return the combined standard uncertainty in percent of the reading."""
    if power_range == "LOW":
        zero_offset_w = 0.5e-9
    elif power_range == "HIGH":
        zero_offset_w = 50e-9
    else:
        raise ValueError('power_range must be "LOW" or "HIGH"')

    reading_w = 10.0 ** (reading_dbm / 10.0) / 1000.0

    if freq_hz <= 8e9:
        calibration_factor_limit = 1.6
        gamma_meter = 0.10
    else:
        calibration_factor_limit = 2.2
        gamma_meter = 0.15

    # Every entry below is a standard uncertainty in percent of reading.
    terms = (
        0.50 / math.sqrt(3.0),
        0.30 / math.sqrt(3.0),
        (100.0 * zero_offset_w / reading_w) / math.sqrt(3.0),
        calibration_factor_limit / 2.0,
        2.0 / math.sqrt(averages),
        (200.0 * gamma_source * gamma_meter) / math.sqrt(2.0),
        ((10.0 ** (0.005 / 10.0) - 1.0) * 100.0) / math.sqrt(3.0),
    )

    return math.sqrt(math.fsum(term * term for term in terms))
